1	#include "rbtree.h"
2	
3	#include <assert.h>
4	#include <stddef.h>
5	#include <stdio.h>
6	#include <stdlib.h>
7	#include <string.h>
8	
9	/* White-box access to rbnode_t / struct rbtree for the invalid-tree fixtures
10	 * in test_rb_validate below -- rbtree_t stays opaque in rbtree.h by design,
11	 * but rb_validate's negative cases can't be built through the public API
12	 * (rb_insert should never itself produce an invalid tree). See Makefile:
13	 * $(SRC) is deliberately not compiled into $(BIN) separately, to avoid
14	 * double-defining the symbols this pulls in. */
15	#include "../src/rbtree.c"
16	
17	/* Provided by tests/fault_malloc.c: forces a specific rb_malloc call inside
18	 * rb_create to return NULL, without touching libc malloc. */
19	extern void fault_malloc_arm(int nth_call_to_fail);
20	extern void fault_malloc_disarm(void);
21	extern int fault_malloc_free_count(void);
22	
23	static int value_free_calls = 0;
24	
25	static void counting_free(void *value)
26	{
27	    (void)value;
28	    value_free_calls++;
29	}
30	
31	static void count_cb(const char *key, void *value, void *ctx)
32	{
33	    (void)key;
34	    (void)value;
35	    (*(int *)ctx)++;
36	}
37	
38	/* Tracks which value pointers the tree has actually freed, so insert tests
39	 * can tell "old value freed on overwrite" apart from "value untouched on
40	 * allocation failure" instead of just trusting the return code. */
41	#define MAX_FREED 16
42	static void *freed_values[MAX_FREED];
43	static int freed_count;
44	
45	static void reset_tracking(void)
46	{
47	    freed_count = 0;
48	}
49	
50	static void track_free(void *value)
51	{
52	    assert(freed_count < MAX_FREED);
53	    freed_values[freed_count++] = value;
54	    free(value);
55	}
56	
57	static int was_freed(void *value)
58	{
59	    for (int i = 0; i < freed_count; i++)
60	        if (freed_values[i] == value)
61	            return 1;
62	    return 0;
63	}
64	
65	#define MAX_COLLECT 16
66	typedef struct {
67	    const char *keys[MAX_COLLECT];
68	    int n;
69	} collect_ctx_t;
70	
71	static void collect_cb(const char *key, void *value, void *ctx)
72	{
73	    (void)value;
74	    collect_ctx_t *c = ctx;
75	    assert(c->n < MAX_COLLECT);
76	    c->keys[c->n++] = key;
77	}
78	
79	typedef struct {
80	    const char *name;
81	    rb_value_free_fn value_free;
82	    int fail_at;          /* 0 = no injected malloc failure */
83	    int expect_nonnull;
84	    int expect_free_count; /* rb_free calls during the faulted create; -1 = n/a */
85	} create_case_t;
86	
87	/* Baseline success (with/without value_free), and injected failure on
88	 * each of rb_create's two allocations (the struct, then the nil
89	 * sentinel). Each row that returns non-NULL also exercises
90	 * destroy-after-success being crash-free and memcheck-clean, and now
91	 * checks rb_validate and that value_free is never spuriously invoked
92	 * on an empty tree.
93	 *
94	 * fail_at assumes rb_create makes exactly two rb_malloc calls, in this
95	 * order: the tree struct, then the nil sentinel. If that allocation
96	 * strategy changes, these cases will fail loudly via expect_nonnull
97	 * rather than silently no-op. expect_free_count values: fail_at=1
98	 * fails before anything is allocated, so cleanup frees nothing (0);
99	 * fail_at=2 fails after the tree struct succeeds, so cleanup frees
100	 * exactly that one allocation (1). */
101	static const create_case_t create_cases[] = {
102	    { "create_null_value_free",    NULL,          0, 1, -1 },
103	    { "create_nonnull_value_free", counting_free, 0, 1, -1 },
104	    { "create_fail_first_alloc",   NULL,          1, 0,  0 },
105	    { "create_fail_second_alloc",  NULL,          2, 0,  1 },
106	};
107	
108	static void test_rb_create(void)
109	{
110	    size_t n = sizeof create_cases / sizeof create_cases[0];
111	    /* invariant: each iteration leaves no allocation armed and no tree
112	     * leaked, regardless of whether rb_create succeeded. */
113	    for (size_t i = 0; i < n; i++) {
114	        const create_case_t *c = &create_cases[i];
115	
116	        if (c->fail_at)
117	            fault_malloc_arm(c->fail_at);
118	        rbtree_t *t = rb_create(c->value_free);
119	        if (c->fail_at) {
120	            assert(fault_malloc_free_count() == c->expect_free_count);
121	            fault_malloc_disarm();
122	        }
123	
124	        assert((t != NULL) == c->expect_nonnull);
125	
126	        if (t) {
127	            assert(rb_size(t) == 0);
128	            assert(rb_validate(t) == 0);
129	            assert(rb_find(t, "probe") == NULL);
130	            int calls = 0;
131	            rb_foreach(t, count_cb, &calls);
132	            assert(calls == 0);
133	            value_free_calls = 0;
134	            rb_destroy(t);
135	            assert(value_free_calls == 0);
136	        }
137	        printf("ok - %s\n", c->name);
138	    }
139	
140	    /* Two live trees don't share hidden state. */
141	    {
142	        rbtree_t *a = rb_create(NULL);
143	        rbtree_t *b = rb_create(NULL);
144	        assert(a && b && a != b);
145	        assert(rb_size(a) == 0 && rb_size(b) == 0);
146	        assert(rb_validate(a) == 0 && rb_validate(b) == 0);
147	        rb_destroy(a);
148	        assert(rb_size(b) == 0);
149	        rb_destroy(b);
150	        printf("ok - create_independent_instances\n");
151	    }
152	
153	    /* rb_destroy is documented NULL-safe. */
154	    {
155	        rb_destroy(NULL);
156	        printf("ok - create_destroy_null_safe\n");
157	    }
158	}
159	
160	/* White-box fixture helper: builds one node directly (bypassing rb_insert)
161	 * so test_rb_validate can wire up structurally-valid-but-invariant-violating
162	 * trees that rb_insert itself should never be able to produce. */
163	static rbnode_t *mk_node(rbtree_t *t, const char *key, int color)
164	{
165	    rbnode_t *n = rb_malloc(sizeof *n);
166	    assert(n);
167	    n->key = rb_malloc(strlen(key) + 1);
168	    assert(n->key);
169	    memcpy(n->key, key, strlen(key) + 1);
170	    n->value = NULL;
171	    n->left = n->right = n->parent = t->nil;
172	    n->color = color;
173	    return n;
174	}
175	
176	/* rb_validate's own TODO lists exactly three invariants: BST order, red
177	 * implies black children, and equal black-height on every root-to-nil path.
178	 * Each case below isolates exactly one of those, and every violation gets
179	 * its left/right (or shallow/deep) mirror so an implementation that only
180	 * checks one side can't pass by accident. */
181	static void test_rb_validate(void)
182	{
183	    /* Cases 1-4: red-red violation (a red node with a red child), at each
184	     * combination of which side of the root the red parent is on and which
185	     * side of that parent the red child is on. Ordering is correct and both
186	     * root-to-nil paths carry the same black count in every case, so only
187	     * the red-red rule is broken. */
188	    {
189	        static const struct {
190	            const char *name;
191	            const char *parent_key;
192	            int parent_is_left;      /* parent is root's left (1) or right (0) child */
193	            const char *child_key;
194	            int child_is_left;       /* red child is parent's left (1) or right (0) child */
195	        } cases[] = {
196	            { "validate_red_red_LL", "d", 1, "b", 1 },
197	            { "validate_red_red_LR", "d", 1, "f", 0 },
198	            { "validate_red_red_RL", "t", 0, "r", 1 },
199	            { "validate_red_red_RR", "t", 0, "v", 0 },
200	        };
201	        for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
202	            rbtree_t *t = rb_create(NULL);
203	            assert(t);
204	
205	            rbnode_t *parent = mk_node(t, cases[i].parent_key, RB_RED);
206	            rbnode_t *child = mk_node(t, cases[i].child_key, RB_RED);
207	            child->parent = parent;
208	            if (cases[i].child_is_left)
209	                parent->left = child;
210	            else
211	                parent->right = child;
212	
213	            rbnode_t *root = mk_node(t, "m", RB_BLACK);
214	            root->parent = t->nil;
215	            if (cases[i].parent_is_left) {
216	                root->left = parent;
217	                root->right = t->nil;
218	            } else {
219	                root->right = parent;
220	                root->left = t->nil;
221	            }
222	            parent->parent = root;
223	            t->root = root;
224	            t->size = 3;
225	
226	            assert(rb_validate(t) != 0);
227	            rb_destroy(t);
228	            printf("ok - %s\n", cases[i].name);
229	        }
230	    }
231	
232	    /* Cases 5-8: BST-order violation. The first two are immediate
233	     * parent/child inversions; the last two are deeper ancestor-bound
234	     * violations -- a node that's fine relative to its immediate parent but
235	     * violates a grandparent's bound, which a validator that only compares
236	     * a node to its direct parent (instead of threading a min/max bound)
237	     * would miss. All nodes BLACK so there's no red-red/black-height noise. */
238	    {
239	        rbtree_t *t = rb_create(NULL);
240	        assert(t);
241	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
242	        rbnode_t *left = mk_node(t, "z", RB_BLACK); /* should be < "m" */
243	        root->left = left;
244	        root->right = t->nil;
245	        root->parent = t->nil;
246	        left->parent = root;
247	        t->root = root;
248	        t->size = 2;
249	        assert(rb_validate(t) != 0);
250	        rb_destroy(t);
251	        printf("ok - validate_bst_order_immediate_left_too_big\n");
252	    }
253	    {
254	        rbtree_t *t = rb_create(NULL);
255	        assert(t);
256	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
257	        rbnode_t *right = mk_node(t, "b", RB_BLACK); /* should be > "m" */
258	        root->right = right;
259	        root->left = t->nil;
260	        root->parent = t->nil;
261	        right->parent = root;
262	        t->root = root;
263	        t->size = 2;
264	        assert(rb_validate(t) != 0);
265	        rb_destroy(t);
266	        printf("ok - validate_bst_order_immediate_right_too_small\n");
267	    }
268	    {
269	        rbtree_t *t = rb_create(NULL);
270	        assert(t);
271	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
272	        rbnode_t *left = mk_node(t, "d", RB_BLACK);       /* valid: "d" < "m" */
273	        rbnode_t *deep = mk_node(t, "x", RB_BLACK);       /* valid vs "d": "x" > "d" ... */
274	        left->right = deep;                               /* ...but "x" > "m" violates root's bound */
275	        left->left = t->nil;
276	        deep->left = deep->right = t->nil;
277	        root->left = left;
278	        root->right = t->nil;
279	        root->parent = t->nil;
280	        left->parent = root;
281	        deep->parent = left;
282	        t->root = root;
283	        t->size = 3;
284	        assert(rb_validate(t) != 0);
285	        rb_destroy(t);
286	        printf("ok - validate_bst_order_deep_left_exceeds_root\n");
287	    }
288	    {
289	        rbtree_t *t = rb_create(NULL);
290	        assert(t);
291	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
292	        rbnode_t *right = mk_node(t, "t", RB_BLACK);      /* valid: "t" > "m" */
293	        rbnode_t *deep = mk_node(t, "c", RB_BLACK);       /* valid vs "t": "c" < "t" ... */
294	        right->left = deep;                                /* ...but "c" < "m" violates root's bound */
295	        right->right = t->nil;
296	        deep->left = deep->right = t->nil;
297	        root->right = right;
298	        root->left = t->nil;
299	        root->parent = t->nil;
300	        right->parent = root;
301	        deep->parent = right;
302	        t->root = root;
303	        t->size = 3;
304	        assert(rb_validate(t) != 0);
305	        rb_destroy(t);
306	        printf("ok - validate_bst_order_deep_right_below_root\n");
307	    }
308	
309	    /* Cases 9-10: black-height mismatch. All nodes BLACK, correct BST
310	     * order, differing only in which side carries an extra black node. */
311	    {
312	        rbtree_t *t = rb_create(NULL);
313	        assert(t);
314	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
315	        rbnode_t *left = mk_node(t, "b", RB_BLACK);
316	        left->left = left->right = t->nil;
317	        root->left = left;
318	        root->right = t->nil; /* one black shorter than the left path */
319	        root->parent = t->nil;
320	        left->parent = root;
321	        t->root = root;
322	        t->size = 2;
323	        assert(rb_validate(t) != 0);
324	        rb_destroy(t);
325	        printf("ok - validate_black_height_left_heavy\n");
326	    }
327	    {
328	        rbtree_t *t = rb_create(NULL);
329	        assert(t);
330	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
331	        rbnode_t *right = mk_node(t, "v", RB_BLACK);
332	        right->left = right->right = t->nil;
333	        root->right = right;
334	        root->left = t->nil; /* one black shorter than the right path */
335	        root->parent = t->nil;
336	        right->parent = root;
337	        t->root = root;
338	        t->size = 2;
339	        assert(rb_validate(t) != 0);
340	        rb_destroy(t);
341	        printf("ok - validate_black_height_right_heavy\n");
342	    }
343	}
344	
345	typedef struct {
346	    const char *name;
347	    const char *key;
348	    void *value;
349	    int fail_at;           /* 0 = no injected malloc failure */
350	    int expect_ok;         /* expect rb_insert to return 0 */
351	} insert_case_t;
352	
353	/* Cases 1-3: baseline success, and injected failure on each of
354	 * rb_insert's internal allocations. Order-agnostic about which
355	 * allocation (node struct vs. key copy) fail_at hits -- the header's
356	 * -1 contract must hold identically either way. */
357	static const insert_case_t insert_cases[] = {
358	    { "insert_into_empty_success", "alpha", "alpha-value", 0, 1 },
359	    { "insert_fails_first_alloc",  "beta",  "beta-value",  1, 0 },
360	    { "insert_fails_second_alloc", "gamma", "gamma-value", 2, 0 },
361	};
362	
363	static void test_rb_insert(void)
364	{
365	    size_t n = sizeof insert_cases / sizeof insert_cases[0];
366	    /* invariant: each iteration gets a fresh tree, so a case's outcome
367	     * never depends on a prior case's inserts. */
368	    for (size_t i = 0; i < n; i++) {
369	        const insert_case_t *c = &insert_cases[i];
370	        rbtree_t *t = rb_create(NULL);
371	        assert(t);
372	
373	        if (c->fail_at)
374	            fault_malloc_arm(c->fail_at);
375	        int rc = rb_insert(t, c->key, c->value);
376	        if (c->fail_at)
377	            fault_malloc_disarm();
378	
379	        assert((rc == 0) == c->expect_ok);
380	        assert(rb_size(t) == (size_t)(c->expect_ok ? 1 : 0));
381	        assert(rb_find(t, c->key) == (c->expect_ok ? c->value : NULL));
382	
383	        rb_destroy(t);
384	        printf("ok - %s\n", c->name);
385	    }
386	
387	    /* Case 4: on allocation failure the tree must not call value_free,
388	     * and the caller must retain sole ownership of value. */
389	    {
390	        rbtree_t *t = rb_create(track_free);
391	        assert(t);
392	        for (int fail_at = 1; fail_at <= 2; fail_at++) {
393	            reset_tracking();
394	            char *v = malloc(8);
395	            assert(v);
396	            strcpy(v, "owned");
397	
398	            fault_malloc_arm(fail_at);
399	            int rc = rb_insert(t, "delta", v);
400	            fault_malloc_disarm();
401	
402	            assert(rc == -1);
403	            assert(!was_freed(v));
404	            assert(rb_size(t) == 0);
405	            free(v);   /* caller still owns it; must not double-free */
406	        }
407	        rb_destroy(t);
408	        printf("ok - insert_failure_value_not_consumed\n");
409	    }
410	
411	    /* Case 5: overwriting an existing key frees the old value via
412	     * value_free, keeps size unchanged, and matches by key content (two
413	     * distinct buffers with identical content, not the same pointer). */
414	    {
415	        rbtree_t *t = rb_create(track_free);
416	        assert(t);
417	        reset_tracking();
418	
419	        char key_first[] = "dup";
420	        char key_second[] = "dup";
421	        char *old_value = malloc(8);
422	        char *new_value = malloc(8);
423	        assert(old_value && new_value);
424	        strcpy(old_value, "old");
425	        strcpy(new_value, "new");
426	
427	        assert(rb_insert(t, key_first, old_value) == 0);
428	        assert(rb_insert(t, key_second, new_value) == 0);
429	
430	        assert(rb_size(t) == 1);
431	        assert(was_freed(old_value));
432	        assert(!was_freed(new_value));
433	        assert(rb_find(t, "dup") == new_value);
434	
435	        rb_destroy(t);
436	        printf("ok - insert_overwrite_frees_old_value\n");
437	    }
438	
439	    /* Case 6: distinct keys each get their own slot; size accumulates
440	     * and lookups don't cross-contaminate. */
441	    {
442	        rbtree_t *t = rb_create(NULL);
443	        assert(t);
444	        assert(rb_insert(t, "a-key", "a-value") == 0);
445	        assert(rb_insert(t, "m-key", "m-value") == 0);
446	        assert(rb_insert(t, "z-key", "z-value") == 0);
447	
448	        assert(rb_size(t) == 3);
449	        assert(strcmp(rb_find(t, "a-key"), "a-value") == 0);
450	        assert(strcmp(rb_find(t, "m-key"), "m-value") == 0);
451	        assert(strcmp(rb_find(t, "z-key"), "z-value") == 0);
452	        assert(rb_find(t, "q-key") == NULL);
453	
454	        rb_destroy(t);
455	        printf("ok - insert_distinct_keys_accumulate_size\n");
456	    }
457	
458	    /* Case 7: an ascending run of inserts forces left-rotations during
459	     * insert-fixup; rebalancing must preserve red-black invariants and
460	     * BST (sorted in-order) structure. */
461	    {
462	        static const char *keys[] = { "a", "b", "c", "d", "e", "f", "g" };
463	        size_t run_len = sizeof keys / sizeof keys[0];
464	        rbtree_t *t = rb_create(NULL);
465	        assert(t);
466	        /* invariant: every insert in this run succeeds before the next
467	         * begins, so size == i+1 after the i-th insert. */
468	        for (size_t i = 0; i < run_len; i++) {
469	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
470	            assert(rb_size(t) == i + 1);
471	        }
472	
473	        assert(rb_validate(t) == 0);
474	
475	        collect_ctx_t collected = {0};
476	        rb_foreach(t, collect_cb, &collected);
477	        assert(collected.n == (int)run_len);
478	        /* invariant: in-order traversal is strictly ascending since all
479	         * inserted keys are distinct. */
480	        for (int i = 0; i + 1 < collected.n; i++)
481	            assert(strcmp(collected.keys[i], collected.keys[i + 1]) < 0);
482	
483	        rb_destroy(t);
484	        printf("ok - insert_rebalances_ascending_run\n");
485	    }
486	
487	    /* Case 8: a descending run of inserts forces right-rotations during
488	     * insert-fixup; same invariants must hold. */
489	    {
490	        static const char *keys[] = { "g", "f", "e", "d", "c", "b", "a" };
491	        size_t run_len = sizeof keys / sizeof keys[0];
492	        rbtree_t *t = rb_create(NULL);
493	        assert(t);
494	        for (size_t i = 0; i < run_len; i++) {
