17	typedef struct rbnode {
18	    char *key;               /* owned copy; NULL on the nil sentinel */
19	    void *value;              /* owned iff value_free != NULL */
20	    struct rbnode *left;
21	    struct rbnode *right;
22	    struct rbnode *parent;
23	    enum { RB_RED, RB_BLACK } color;
24	} rbnode_t;
25	
26	struct rbtree {
27	    rbnode_t *root;           /* == nil when empty */
28	    rbnode_t *nil;            /* shared black sentinel leaf; not counted in size */
29	    size_t size;
30	    rb_value_free_fn value_free;
31	};
32	
33	rbtree_t *rb_create(rb_value_free_fn value_free)
34	{
35	    rbtree_t *t = rb_malloc(sizeof *t);
36	    if (!t)
37	        return NULL;                 /* nothing allocated yet, nothing to free */
38	
39	    rbnode_t *nil = rb_malloc(sizeof *nil);
40	    if (!nil)
41	        goto cleanup_tree;           /* second alloc failed, unwind the first */
42	
43	    nil->color  = RB_BLACK;
44	    nil->key    = NULL;
